/**
 * Demo seed: "Executive Financials Demo".
 *
 * Everything here is fictional demo data. Prices come from the accounting recipe's demo values,
 * and demo activity is generated by running real sessions through the production quote services
 * (then back-dated so the dashboard shows a 30-day history).
 *
 *   npm run db:seed            create the demo if missing
 *   npm run db:seed -- --reset delete and recreate ONLY the demo organization
 */
import "dotenv/config";
import { prisma } from "../src/server/db";
import { auth } from "../src/server/auth";
import { ConsoleEmailProvider, LogChatProvider, setProvidersForTesting } from "../src/server/providers";
import { createOrganization } from "../src/server/services/organizations";
import { completeSession, startSession, submitLead, updateSession, markAbandonedSessions } from "../src/server/services/quote-flow";

const DEMO_SLUG = "executive-financials";
const OWNER = { email: "demo@quoteos.dev", password: "demo-password-123", name: "Dana Demo" };
const ADVISOR = { email: "advisor@quoteos.dev", password: "demo-password-123", name: "Alex Advisor" };

async function ensureUser(u: typeof OWNER) {
  const existing = await prisma.user.findUnique({ where: { email: u.email } });
  if (existing) return existing;
  await auth.api.signUpEmail({ body: { email: u.email, password: u.password, name: u.name } });
  return prisma.user.findUniqueOrThrow({ where: { email: u.email } });
}

// Deterministic pseudo-random generator so the demo looks the same on every seed.
let seed = 42;
const rand = () => ((seed = (seed * 1_103_515_245 + 12_345) % 2 ** 31) / 2 ** 31);
const pick = <T,>(xs: T[]) => xs[Math.floor(rand() * xs.length)];

const CHANNELS = [
  { source: "instagram", medium: "paid_social", campaign: "bookkeeping-september", weight: 5 },
  { source: "google", medium: "cpc", campaign: "tax-season", weight: 4 },
  { source: "facebook", medium: "paid_social", campaign: "payroll-q3", weight: 2 },
  { source: null, medium: null, campaign: null, referrer: "https://www.google.com/", weight: 3 },
  { source: "newsletter", medium: "email", campaign: "october-update", weight: 1 },
  { source: null, medium: null, campaign: null, weight: 3 },
];
const weighted = () => {
  const total = CHANNELS.reduce((s, c) => s + c.weight, 0);
  let r = rand() * total;
  for (const c of CHANNELS) if ((r -= c.weight) <= 0) return c;
  return CHANNELS[0];
};

const COMPANIES = [
  ["Harbour View Construction", "Maya Rolle"],
  ["Coral Reef Café", "Devon Knowles"],
  ["Pinewood Dental Studio", "Priya Shah"],
  ["Blue Lagoon Tours", "Marcus Ferguson"],
  ["Sandbar Retail Co.", "Olivia Pratt"],
  ["Northstar Logistics", "Ethan Moss"],
  ["Palm Grove Realty", "Sophia Cartwright"],
  ["Tidewater Consulting", "Liam Bethel"],
  ["Island Bloom Florists", "Ava Munroe"],
  ["Keystone Engineering", "Noah Saunders"],
  ["Seaside Physio", "Grace Albury"],
  ["Driftwood Design Studio", "Jacob Wells"],
];

function bookkeepingAnswers() {
  const payroll = rand() > 0.45;
  return {
    monthlyTransactions: pick([80, 150, 240, 320, 450, 700, 1200]),
    bankAccounts: pick([1, 2, 3, 4]),
    payroll,
    ...(payroll ? { employees: pick([3, 6, 8, 12, 20]) } : {}),
    accountingSoftware: pick(["quickbooks", "xero", "none", "sage"]),
    reportingFrequency: pick(["monthly", "quarterly", "quarterly", "annually"]),
    industry: pick(["construction", "retail", "hospitality", "professional_services", "real_estate"]),
    timeline: pick(["within_30_days", "within_30_days", "one_to_three_months", "researching"]),
  };
}

const SCENARIOS: { service: string; answers: () => Record<string, unknown>; weight: number }[] = [
  { service: "bookkeeping", answers: bookkeepingAnswers, weight: 6 },
  {
    service: "payroll",
    answers: () => ({ employees: pick([4, 9, 15, 30]), payFrequency: pick(["weekly", "biweekly", "monthly"]), contractors: pick([0, 0, 2, 5]), existingSoftware: pick(["gusto", "spreadsheet", "none"]), timeline: pick(["within_30_days", "one_to_three_months"]) }),
    weight: 3,
  },
  {
    service: "vat",
    answers: () => {
      const reg = pick(["yes", "yes", "no"]);
      return { businessType: pick(["company", "sole_trader"]), monthlyRevenue: pick([20_000, 60_000, 140_000]), vatRegistered: reg, ...(reg === "yes" ? { filingFrequency: pick(["quarterly", "monthly"]) } : {}), importsExports: rand() > 0.6, timeline: "one_to_three_months" };
    },
    weight: 2,
  },
  {
    service: "tax-preparation",
    answers: () => {
      const entity = pick(["individual", "sole_prop", "corporation"]);
      return { entityType: entity, ...(entity !== "individual" ? { annualRevenue: pick([150_000, 600_000]) } : {}), incomeSources: pick([["employment"], ["business", "rental"], ["business", "investments"]]), jurisdictions: pick([1, 1, 2]), priorYearsBehind: pick([0, 0, 1]), timeline: pick(["within_30_days", "researching"]) };
    },
    weight: 2,
  },
  { service: "audit", answers: () => ({ auditType: pick(["lender", "statutory"]), annualRevenue: pick([2_500_000, 8_000_000]), entities: pick([1, 3]), timeline: "within_30_days" }), weight: 1 },
  { service: "financial-advisory", answers: () => ({ goals: pick([["cash_flow", "budgeting"], ["cfo"], ["fundraising"]]), companyStage: pick(["growing", "established"]), timeline: "one_to_three_months" }), weight: 1 },
];
const pickScenario = () => {
  const total = SCENARIOS.reduce((s, c) => s + c.weight, 0);
  let r = rand() * total;
  for (const c of SCENARIOS) if ((r -= c.weight) <= 0) return c;
  return SCENARIOS[0];
};

async function backdate(sessionId: string, at: Date) {
  const minutes = (n: number) => new Date(at.getTime() + n * 60_000);
  await prisma.quoteSession.update({ where: { id: sessionId }, data: { startedAt: at, lastActivityAt: minutes(3) } });
  await prisma.quoteSession.updateMany({ where: { id: sessionId, completedAt: { not: null } }, data: { completedAt: minutes(3) } });
  await prisma.quote.updateMany({ where: { quoteSessionId: sessionId }, data: { generatedAt: minutes(3) } });
  await prisma.lead.updateMany({ where: { quoteSessionId: sessionId }, data: { createdAt: minutes(5) } });
  const lead = await prisma.lead.findUnique({ where: { quoteSessionId: sessionId } });
  await prisma.event.updateMany({ where: { OR: [{ quoteSessionId: sessionId }, ...(lead ? [{ leadId: lead.id }] : [])] }, data: { createdAt: minutes(2) } });
  await prisma.event.updateMany({ where: { quoteSessionId: sessionId, type: "QUOTE_STARTED" }, data: { createdAt: at } });
  if (lead) {
    await prisma.task.updateMany({ where: { leadId: lead.id }, data: { createdAt: minutes(5), dueAt: minutes(60 * 24) } });
    await prisma.outboundMessage.updateMany({ where: { leadId: lead.id }, data: { createdAt: minutes(5) } });
  }
}

async function main() {
  const reset = process.argv.includes("--reset");
  setProvidersForTesting({ email: new ConsoleEmailProvider({ silent: true }), whatsapp: new LogChatProvider("whatsapp:seed"), sms: new LogChatProvider("sms:seed") });

  const existing = await prisma.organization.findUnique({ where: { slug: DEMO_SLUG } });
  if (existing && !reset) {
    console.log(`Demo organization "${DEMO_SLUG}" already exists (use --reset to recreate it).`);
    return;
  }
  if (existing) {
    await prisma.organization.delete({ where: { id: existing.id } }); // cascades to this org's data only
    console.log("Deleted existing demo organization.");
  }

  const owner = await ensureUser(OWNER);
  const advisor = await ensureUser(ADVISOR);

  const org = await createOrganization(owner.id, {
    name: "Executive Financials Demo",
    slug: DEMO_SLUG,
    recipeKey: "accounting",
    templateKey: "professional",
    currency: "USD",
    timezone: "America/Nassau",
    contactEmail: "hello@executivefinancials.example",
    contactPhone: "+1 (242) 555-0142",
  });
  await prisma.organization.update({
    where: { id: org.id },
    data: {
      notificationEmail: "leads@executivefinancials.example",
      bookingUrl: "https://booking.example.com/executive-financials-demo",
      website: "https://executivefinancials.example",
    },
  });
  await prisma.membership.create({ data: { organizationId: org.id, userId: advisor.id, role: "MEMBER" } });

  // Generate ~30 days of demo activity through the real services.
  const now = Date.now();
  let leads = 0;
  let people = 0;
  for (let i = 0; i < 58; i++) {
    const daysAgo = Math.floor(rand() * 29) + 1;
    const at = new Date(now - daysAgo * 86_400_000 - Math.floor(rand() * 10) * 3_600_000);
    const channel = weighted();
    const scenario = pickScenario();
    const visitorId = `demo-visitor-${i}`;
    const attribution = { source: channel.source, medium: channel.medium, campaign: channel.campaign, referrer: "referrer" in channel ? channel.referrer : null, landingPage: `https://executivefinancials.example/quote?utm_source=${channel.source ?? ""}` };

    // Some visitors only view the page.
    await prisma.event.create({ data: { organizationId: org.id, type: "QUOTE_VIEWED", visitorId, createdAt: at, payload: { source: channel.source ?? "direct" } } });
    if (rand() < 0.22) continue;

    const s = await startSession(DEMO_SLUG, { serviceSlug: scenario.service, visitorId, attribution });
    const answers = scenario.answers();
    const abandon = rand() < 0.2;
    if (abandon) {
      const [k, v] = Object.entries(answers)[0];
      await updateSession(DEMO_SLUG, s.sessionId, s.token, { answers: { [k]: v }, currentStep: 1 });
      await backdate(s.sessionId, at);
      continue;
    }
    await updateSession(DEMO_SLUG, s.sessionId, s.token, { answers, currentStep: Object.keys(answers).length });
    await completeSession(DEMO_SLUG, s.sessionId, s.token);
    if (rand() < 0.78) {
      const [company, name] = COMPANIES[people++ % COMPANIES.length];
      const suffix = people > COMPANIES.length ? ` ${Math.ceil(people / COMPANIES.length)}` : "";
      const email = `${name.split(" ")[0].toLowerCase()}${suffix.trim()}@${company.toLowerCase().replace(/[^a-z]+/g, "")}.example`;
      const r = await submitLead(DEMO_SLUG, s.sessionId, s.token, { name, company: company + suffix, email, phone: "+1 242 555 01" + String(10 + (people % 89)).padStart(2, "0") });
      leads++;
      // Move some leads along the pipeline.
      const roll = rand();
      const status = roll < 0.18 ? "CONTACTED" : roll < 0.3 ? "QUALIFIED" : roll < 0.36 ? "PROPOSAL_SENT" : roll < 0.44 ? "WON" : roll < 0.48 ? "LOST" : null;
      if (status && r.status !== "NEEDS_REVIEW") {
        await prisma.lead.update({ where: { id: r.leadId }, data: { status, ownerId: rand() > 0.5 ? advisor.id : owner.id } });
      }
      if (rand() < 0.25) {
        await prisma.appointment.create({ data: { organizationId: org.id, leadId: r.leadId, provider: "demo", startsAt: new Date(at.getTime() + 3 * 86_400_000) } });
        await prisma.event.create({ data: { organizationId: org.id, type: "CONSULTATION_BOOKED", leadId: r.leadId, createdAt: new Date(at.getTime() + 86_400_000), payload: { provider: "demo" } } });
      }
    }
    await backdate(s.sessionId, at);
  }
  // Leave idle incomplete sessions marked as abandoned, as the scheduled job would.
  await markAbandonedSessions({ organizationId: org.id, idleMinutes: 30 });

  console.log(`
Executive Financials Demo is ready (${leads} demo leads).

  Quote funnel:   /q/${DEMO_SLUG}
                  /q/${DEMO_SLUG}?service=bookkeeping&utm_source=instagram&utm_campaign=bookkeeping-september
  Try templates:  /q/${DEMO_SLUG}?template=modern   /q/${DEMO_SLUG}?template=premium
  Dashboard:      /dashboard/${DEMO_SLUG}
  Sign in:        ${OWNER.email} / ${OWNER.password}   (member: ${ADVISOR.email} / ${ADVISOR.password})

All prices and data are fictional demo values.`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(() => prisma.$disconnect());
